const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

const AdminDashboard: React.FC = () => {
  const [logs, setLogs] = useState<DailyLog[]>([]);
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [loadingAi, setLoadingAi] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    setLogs(getAllLogs());
  }, []);

  const handleAiAnalysis = async () => {
    if (logs.length === 0) return;
    setLoadingAi(true);
    const result = await analyzeDailyLogs(logs);
    setAiAnalysis(result);
    setLoadingAi(false);
  };

  // Data Aggregation for Charts
  const revenueByDriver = logs.reduce((acc, log) => {
    const existing = acc.find(a => a.name === log.driverName);
    if (existing) {
      existing.value += log.totalInvoiced;
    } else {
      acc.push({ name: log.driverName, value: log.totalInvoiced });
    }
    return acc;
  }, [] as { name: string; value: number }[]);

  const filteredLogs = logs.filter(log => 
    log.driverName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    log.vehicleId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-20">

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
           <p className="text-gray-500 text-sm">Faturamento Total</p>
           <h3 className="text-2xl font-bold text-gray-800">
             R$ {logs.reduce((acc, l) => acc + l.totalInvoiced, 0).toFixed(2)}
           </h3>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
           <p className="text-gray-500 text-sm">Serviços Realizados</p>
           <h3 className="text-2xl font-bold text-indigo-600">
             {logs.reduce((acc, l) => acc + l.services.length, 0)}
           </h3>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
           <p className="text-gray-500 text-sm">Motoristas Ativos</p>
           <h3 className="text-2xl font-bold text-gray-800">
             {new Set(logs.map(l => l.userId)).size}
           </h3>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
           <p className="text-gray-500 text-sm">Despesas Totais</p>
           <h3 className="text-2xl font-bold text-red-500">
             R$ {logs.reduce((acc, l) => acc + l.totalExpenses, 0).toFixed(2)}
           </h3>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Charts */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-gray-500"/> Performance por Motorista
          </h3>
          <div className="h-64">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={revenueByDriver}>
                 <CartesianGrid strokeDasharray="3 3" />
                 <XAxis dataKey="name" />
                 <YAxis />
                 <Tooltip />
                 <Bar dataKey="value" fill="#4f46e5" name="Faturamento (R$)" />
               </BarChart>
             </ResponsiveContainer>
          </div>
        </div>

        {/* AI Analysis Section */}
        <div className="bg-gradient-to-br from-indigo-600 to-purple-700 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
          <div className="relative z-10">
            <h3 className="text-lg font-bold mb-2 flex items-center gap-2">
              <Bot className="w-6 h-6" /> Assistente Gemini IA
            </h3>
            <p className="text-indigo-100 text-sm mb-4">
              Analise os logs diários para identificar padrões, motoristas de destaque e anomalias financeiras.
            </p>

            {!aiAnalysis ? (
              <button 
                onClick={handleAiAnalysis}
                disabled={loadingAi}
                className="w-full bg-white text-indigo-700 font-bold py-2 px-4 rounded-lg shadow-md hover:bg-gray-50 transition-colors disabled:opacity-70"
              >
                {loadingAi ? 'Analisando dados...' : 'Gerar Relatório Diário'}
              </button>
            ) : (
               <div className="mt-4 bg-white/10 p-4 rounded-lg text-sm leading-relaxed max-h-80 overflow-y-auto backdrop-blur-sm scrollbar-thin scrollbar-thumb-white/20">
                 <ReactMarkdown>{aiAnalysis}</ReactMarkdown>
                 <button onClick={() => setAiAnalysis('')} className="mt-4 text-xs underline text-indigo-200">Limpar</button>
               </div>
            )}
          </div>
          {/* Decorative Circle */}
          <div className="absolute -bottom-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-2xl"></div>
        </div>
      </div>

      {/* Detailed Logs Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
         <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
            <h3 className="text-lg font-semibold flex items-center gap-2">
              <FileText className="w-5 h-5 text-gray-500"/> Registros Recebidos
            </h3>
            <div className="relative">
               <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
               <input 
                 type="text"
                 placeholder="Buscar motorista ou VTR..."
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:ring-indigo-500 focus:border-indigo-500 w-64"
               />
            </div>
         </div>
         <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
               <thead className="bg-gray-50">
                  <tr>
                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Data</th>
                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Motorista</th>
                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Veículo</th>
                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">KM Rodado</th>
                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Faturamento</th>
                     <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Obs</th>
                  </tr>
               </thead>
               <tbody className="bg-white divide-y divide-gray-200">
                  {filteredLogs.length > 0 ? filteredLogs.map(log => (
                    <tr key={log.id} className="hover:bg-gray-50">
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{log.date}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{log.driverName}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{log.vehicleId.toUpperCase()}</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{log.kmEnd - log.kmStart} km</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-green-600 font-semibold">R$ {log.totalInvoiced.toFixed(2)}</td>
                       <td className="px-6 py-4 text-sm text-gray-500 max-w-xs truncate">{log.observations || '-'}</td>
                    </tr>
                  )) : (
                    <tr>
                       <td colSpan={6} className="px-6 py-10 text-center text-gray-500">Nenhum registro encontrado.</td>
                    </tr>
                  )}
               </tbody>
            </table>
         </div>
      </div>

    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './components/Login';
import DriverForm from './components/DriverForm';
import AdminDashboard from './components/AdminDashboard';
import { User, UserRole } from './types';
import { getCurrentUser, setCurrentUser } from './services/storage';
import { LogOut, LayoutDashboard, FilePlus } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedUser = getCurrentUser();
    if (storedUser) {
      setUser(storedUser);
    }
  }, []);

  const handleLogin = (newUser: User) => {
    setUser(newUser);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setUser(null);
  };

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <Router>
       <div className="min-h-screen flex flex-col">
          {/* Navigation Bar */}
          <nav className="bg-white border-b border-gray-200 sticky top-0 z-50">
             <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex justify-between h-16">
                   <div className="flex items-center gap-3">
                      <div className="bg-indigo-600 p-2 rounded-lg">
                        <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
                      </div>
                      <div>
                        <span className="font-bold text-xl tracking-tight text-gray-900">GuinchoLog</span>
                        <span className="text-xs block text-gray-500 -mt-1">{user.role === UserRole.ADMIN ? 'Painel Administrativo' : 'Portal do Motorista'}</span>
                      </div>
                   </div>

                   <div className="flex items-center gap-4">
                      <div className="hidden md:flex flex-col items-end mr-2">
                         <span className="text-sm font-medium text-gray-900">{user.name}</span>
                         <span className="text-xs text-gray-500">{user.email}</span>
                      </div>
                      <img src={user.avatarUrl} alt="Avatar" className="w-10 h-10 rounded-full border-2 border-indigo-100" />
                      <button 
                        onClick={handleLogout}
                        className="p-2 text-gray-400 hover:text-red-600 transition-colors rounded-full hover:bg-gray-100"
                        title="Sair"
                      >
                         <LogOut className="w-5 h-5" />
                      </button>
                   </div>
                </div>
             </div>
          </nav>

          {/* Main Content Area */}
          <main className="flex-1 bg-gray-50 pt-8 px-4 sm:px-6 lg:px-8">
             {user.role === UserRole.ADMIN ? (
               <AdminDashboard />
             ) : (
               <DriverForm user={user} onSuccess={() => alert("Relatório enviado com sucesso!")} />
             )}
          </main>
       </div>
    </Router>
  );
};

