  // Let's assume Cash + Debit + Pix is "Avista" for the form logic based on the image "Líquido À Vista"
  const totalLiquidCash = services
    .filter(s => [PaymentMethod.CASH, PaymentMethod.DEBIT, PaymentMethod.PIX].includes(s.paymentMethod))
    .reduce((acc, curr) => acc + (Number(curr.value) || 0), 0) - totalExpenses;

