              </div>
            )}

            {services.map((service, index) => (
              <div key={service.id} className="bg-gray-50 rounded-lg p-4 border border-gray-200 shadow-sm relative animate-fade-in-up">
                <div className="absolute top-2 right-2">
                   <button onClick={() => removeServiceRow(service.id)} className="text-red-400 hover:text-red-600">
                     <Trash2 className="w-5 h-5" />
                   </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  {/* Row 1 */}
                  <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><Clock className="w-3 h-3"/> Início</label>
                    <input type="time" value={service.startTime} onChange={(e) => updateService(service.id, 'startTime', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><Clock className="w-3 h-3"/> Fim</label>
                    <input type="time" value={service.endTime} onChange={(e) => updateService(service.id, 'endTime', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><MapPin className="w-3 h-3"/> Saída</label>
                    <input type="text" placeholder="Local de Saída" value={service.departure} onChange={(e) => updateService(service.id, 'departure', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                   <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><MapPin className="w-3 h-3"/> Destino</label>
                    <input type="text" placeholder="Local de Destino" value={service.destination} onChange={(e) => updateService(service.id, 'destination', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>

                  {/* Row 2 - Reordered: Payment THEN Value */}
                   <div>
                     <label className="text-xs text-gray-500">Veículo Rebocado</label>
                    <input type="text" placeholder="Modelo/Cor" value={service.towedVehicle} onChange={(e) => updateService(service.id, 'towedVehicle', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                   <div>
                     <label className="text-xs text-gray-500">Placa</label>
                    <input type="text" placeholder="ABC-1234" value={service.towedPlate} onChange={(e) => updateService(service.id, 'towedPlate', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 uppercase bg-white text-gray-900" />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Cliente</label>
                    <input type="text" placeholder="Nome" value={service.clientName} onChange={(e) => updateService(service.id, 'clientName', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>

                   {/* Payment Method - Explicit Styles */}
                   <div>
                    <label className="text-xs text-gray-500 font-medium">Pagamento</label>
                    <select 
