import React, { useState } from 'react';
import { User, UserRole } from '../types';
import { MOCK_ADMIN, MOCK_DRIVERS } from '../constants';
import { setCurrentUser } from '../services/storage';
import { Lock, User as UserIcon, LogIn } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [identifier, setIdentifier] = useState(''); // Can be Email or CPF
  const [isAdmin, setIsAdmin] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isAdmin) {
      // Simple Admin check for demo (in real app, use real auth)
      if (identifier === 'admin' || identifier === MOCK_ADMIN.email) {
        setCurrentUser(MOCK_ADMIN);
        onLogin(MOCK_ADMIN);
      } else {
        setError('Credenciais de administrador inválidas.');
      }
      return;
    }

    // Driver Login Check
    const cleanIdentifier = identifier.trim().toLowerCase();
    const cleanCPF = identifier.replace(/\D/g, ''); // Remove non-digits for CPF check

    const driver = MOCK_DRIVERS.find(d => 
      d.email.toLowerCase() === cleanIdentifier || 
      (d.cpf && d.cpf.replace(/\D/g, '') === cleanCPF)
    );

    if (driver) {
      setCurrentUser(driver);
      onLogin(driver);
    } else {
      setError('Motorista não encontrado. Verifique seu Email ou CPF.');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1605218427306-022ba8c69a38?q=80&w=2000&auto=format&fit=crop')] bg-cover bg-center opacity-20"></div>
      <div className="absolute inset-0 bg-gradient-to-t from-gray-900 via-gray-900/90 to-transparent"></div>

      <div className="relative z-10 w-full max-w-md p-8 bg-white/10 backdrop-blur-lg rounded-2xl shadow-2xl border border-white/20">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-white mb-2 tracking-tight">GuinchoLog</h1>
          <p className="text-blue-200">Acesso ao Sistema</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          <div>
            <div className="flex justify-center space-x-4 mb-6">
               <button
                 type="button"
                 onClick={() => { setIsAdmin(false); setError(''); }}
                 className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${!isAdmin ? 'bg-indigo-600 text-white' : 'bg-white/10 text-gray-300 hover:bg-white/20'}`}
               >
                 Sou Motorista
               </button>
               <button
                 type="button"
                 onClick={() => { setIsAdmin(true); setError(''); }}
                 className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${isAdmin ? 'bg-indigo-600 text-white' : 'bg-white/10 text-gray-300 hover:bg-white/20'}`}
               >
                 Sou Administrador
               </button>
            </div>

            <label className="block text-sm font-medium text-gray-300 mb-2">
              {isAdmin ? 'Usuário ou Email' : 'Email ou CPF'}
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <UserIcon className="h-5 w-5 text-gray-400" />
              </div>
              <input
                type="text"
                value={identifier}
                onChange={(e) => setIdentifier(e.target.value)}
                className="block w-full pl-10 pr-3 py-3 border border-gray-600 rounded-lg leading-5 bg-gray-800/50 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                placeholder={isAdmin ? "admin" : "Digite seu email ou CPF"}
                required
              />
            </div>
          </div>

          {error && (
            <div className="p-3 bg-red-500/20 border border-red-500/50 rounded-lg text-red-200 text-sm text-center">
              {error}
            </div>
          )}

          <button
            type="submit"
            className="w-full flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-3 px-4 rounded-xl transition-all duration-200 shadow-lg hover:shadow-indigo-500/30 transform hover:-translate-y-0.5"
          >
            <LogIn className="w-5 h-5" />
            {isAdmin ? 'Entrar no Painel' : 'Iniciar Turno'}
          </button>
        </form>

        {!isAdmin && (
          <p className="mt-6 text-center text-gray-400 text-xs">
            Seu acesso deve estar cadastrado na planilha central.
          </p>
        )}
      </div>
    </div>
  );
};

export default Login;

import { DailyLog, User } from '../types';
import { GOOGLE_SHEET_API_URL } from '../constants';

const LOGS_KEY = 'guincholog_logs';
const USER_KEY = 'guincholog_user';

export const saveLog = (log: DailyLog): void => {
  const existingLogs = getAllLogs();
  // Filter out if updating existing ID, or just append
  const filtered = existingLogs.filter(l => l.id !== log.id);
  const updated = [...filtered, log];
  localStorage.setItem(LOGS_KEY, JSON.stringify(updated));
};

export const getAllLogs = (): DailyLog[] => {
  const str = localStorage.getItem(LOGS_KEY);
  return str ? JSON.parse(str) : [];
};

export const getLogsByUser = (userId: string): DailyLog[] => {
  const all = getAllLogs();
  return all.filter(log => log.userId === userId).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
};

export const getCurrentUser = (): User | null => {
  const str = localStorage.getItem(USER_KEY);
  return str ? JSON.parse(str) : null;
};

export const setCurrentUser = (user: User | null): void => {
  if (user) {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  } else {
    localStorage.removeItem(USER_KEY);
  }
};

export const syncWithGoogleSheets = async (log: DailyLog): Promise<boolean> => {
  if (!GOOGLE_SHEET_API_URL) {
    console.warn("URL da API do Google Sheets não configurada.");
    return false;
  }

  try {
    const response = await fetch(GOOGLE_SHEET_API_URL, {
      method: 'POST',
      mode: 'no-cors', // Google Scripts usually require no-cors for simple POSTs from browser
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(log)
    });

    // With no-cors, we can't check response.ok, so we assume success if no error thrown
    return true;
  } catch (error) {
    console.error("Erro ao enviar para Google Sheets:", error);
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { User, Vehicle, DailyLog, ServiceItem, ExpenseItem, PaymentMethod } from '../types';
import { VEHICLES, GOOGLE_SHEET_API_URL } from '../constants';
import { saveLog, syncWithGoogleSheets } from '../services/storage';
import { Plus, Trash2, Save, Truck, DollarSign, Clock, MapPin, User as UserIcon, Loader2, Share2, CheckCircle } from 'lucide-react';

const generateId = () => Math.random().toString(36).substr(2, 9);

interface DriverFormProps {
  user: User;
  onSuccess: () => void;
}

const DriverForm: React.FC<DriverFormProps> = ({ user, onSuccess }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedVehicle, setSelectedVehicle] = useState('');
  const [kmStart, setKmStart] = useState<number>(0);
  const [kmEnd, setKmEnd] = useState<number>(0);
  const [observations, setObservations] = useState('');

  const [services, setServices] = useState<ServiceItem[]>([]);
  const [expenses, setExpenses] = useState<ExpenseItem[]>([]);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  // Calculations
  const totalInvoiced = services.reduce((acc, curr) => acc + (Number(curr.value) || 0), 0);
  const totalExpenses = expenses.reduce((acc, curr) => acc + (Number(curr.value) || 0), 0);

  // Breakdown
  const totalLiquidTerm = services
    .filter(s => s.paymentMethod === PaymentMethod.ON_TERM || s.paymentMethod === PaymentMethod.CREDIT)
    .reduce((acc, curr) => acc + (Number(curr.value) || 0), 0);

  const totalLiquidCash = services
    .filter(s => [PaymentMethod.CASH, PaymentMethod.DEBIT, PaymentMethod.PIX].includes(s.paymentMethod))
    .reduce((acc, curr) => acc + (Number(curr.value) || 0), 0) - totalExpenses;

  const addServiceRow = () => {
    setServices([
      ...services,
      {
        id: generateId(),
        startTime: '',
        endTime: '',
        departure: '',
        destination: '',
        towedVehicle: '',
        towedPlate: '',
        clientName: '',
        clientPhone: '',
        paymentMethod: PaymentMethod.CASH,
        value: 0
      }
    ]);
  };

  const removeServiceRow = (id: string) => {
    setServices(services.filter(s => s.id !== id));
  };

  const updateService = (id: string, field: keyof ServiceItem, value: any) => {
    setServices(services.map(s => s.id === id ? { ...s, [field]: value } : s));
  };

  const handlePaymentChange = (id: string, method: PaymentMethod) => {
    setServices(services.map(s => {
      if (s.id === id) {
        return {
          ...s,
          paymentMethod: method,
          value: method === PaymentMethod.ON_TERM ? 0 : s.value
        };
      }
      return s;
    }));
  };

  const addExpenseRow = () => {
    setExpenses([...expenses, { id: generateId(), description: '', value: 0 }]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedVehicle) {
      alert("Por favor, selecione um veículo.");
      return;
    }

    const hasInvalidValue = services.some(service => {
      const isTerm = service.paymentMethod === PaymentMethod.ON_TERM;
      const hasValue = service.value && service.value > 0;
      return !isTerm && !hasValue;
    });

    if (hasInvalidValue) {
      alert("Para pagamentos em Dinheiro, Pix, Crédito ou Débito, o valor do serviço é obrigatório.");
      return;
    }

    setIsSubmitting(true);

    const log: DailyLog = {
      id: generateId(),
      userId: user.id,
      driverName: user.name,
      date,
      vehicleId: selectedVehicle,
      kmStart,
      kmEnd,
      services,
      expenses,
      observations,
      totalInvoiced,
      totalLiquidCash,
      totalLiquidTerm,
      totalExpenses,
      submittedAt: new Date().toISOString()
    };

    // 1. Save Local (Backup)
    saveLog(log);

    // 2. Send to Google Sheets (if configured)
    let syncSuccess = false;
    if (GOOGLE_SHEET_API_URL) {
      syncSuccess = await syncWithGoogleSheets(log);
    } else {
      // Simulate delay if no API
      await new Promise(r => setTimeout(r, 1000));
    }

    setIsSubmitting(false);
    setShowSuccessModal(true);
  };

  const finishProcess = () => {
    setShowSuccessModal(false);
    onSuccess(); // Reset or redirect
  };

  if (showSuccessModal) {
    return (
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
        <div className="bg-white rounded-2xl p-6 max-w-sm w-full text-center shadow-xl">
          <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
            <CheckCircle className="w-8 h-8 text-green-600" />
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">Relatório Enviado!</h3>
          <p className="text-gray-600 mb-6">
            Os dados foram salvos com sucesso.
            {!GOOGLE_SHEET_API_URL && <span className="block mt-2 text-xs text-orange-500 font-medium">(Atenção: Planilha Google não conectada. Dados salvos apenas neste celular.)</span>}
          </p>
          <button 
            onClick={finishProcess}
            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-xl"
          >
            OK, Fechar
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto space-y-6 pb-20">
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
        <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
          <Truck className="w-6 h-6 text-indigo-600" />
          Controle Diário de Serviços
        </h2>

        {/* Header Fields */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Data</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="w-full rounded-lg border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2 border text-gray-900 bg-white"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Veículo (Guincho)</label>
            <select 
              value={selectedVehicle} 
              onChange={(e) => setSelectedVehicle(e.target.value)}
              className="w-full rounded-lg border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2 border text-gray-900 bg-white"
            >
              <option value="">Selecione...</option>
              {VEHICLES.map(v => (
                <option key={v.id} value={v.id}>{v.name}</option>
              ))}
            </select>
          </div>
          <div className="flex gap-4">
             <div className="flex-1">
                <label className="block text-sm font-medium text-gray-700 mb-1">KM Início</label>
                <input 
                  type="number" 
                  value={kmStart}
                  onChange={(e) => setKmStart(Number(e.target.value))}
                  className="w-full rounded-lg border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2 border text-gray-900 bg-white"
                />
             </div>
             <div className="flex-1">
                <label className="block text-sm font-medium text-gray-700 mb-1">KM Final</label>
                <input 
                  type="number" 
                  value={kmEnd}
                  onChange={(e) => setKmEnd(Number(e.target.value))}
                  className="w-full rounded-lg border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 p-2 border text-gray-900 bg-white"
                />
             </div>
          </div>
        </div>

        {/* Services Grid - Responsive */}
        <div className="mb-8">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold text-gray-800">Serviços Realizados</h3>
            <button 
              type="button" 
              onClick={addServiceRow}
              className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
            >
              <Plus className="w-4 h-4 mr-1" /> Adicionar Serviço
            </button>
          </div>

          <div className="space-y-4">
            {services.length === 0 && (
              <div className="text-center py-10 bg-gray-50 rounded-lg border-2 border-dashed border-gray-300">
                <p className="text-gray-500">Nenhum serviço registrado hoje.</p>
              </div>
            )}

            {services.map((service, index) => (
              <div key={service.id} className="bg-gray-50 rounded-lg p-4 border border-gray-200 shadow-sm relative animate-fade-in-up">
                <div className="absolute top-2 right-2">
                   <button onClick={() => removeServiceRow(service.id)} className="text-red-400 hover:text-red-600">
                     <Trash2 className="w-5 h-5" />
                   </button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  {/* Row 1 */}
                  <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><Clock className="w-3 h-3"/> Início</label>
                    <input type="time" value={service.startTime} onChange={(e) => updateService(service.id, 'startTime', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><Clock className="w-3 h-3"/> Fim</label>
                    <input type="time" value={service.endTime} onChange={(e) => updateService(service.id, 'endTime', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><MapPin className="w-3 h-3"/> Saída</label>
                    <input type="text" placeholder="Local de Saída" value={service.departure} onChange={(e) => updateService(service.id, 'departure', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                   <div>
                    <label className="text-xs text-gray-500 flex items-center gap-1"><MapPin className="w-3 h-3"/> Destino</label>
                    <input type="text" placeholder="Local de Destino" value={service.destination} onChange={(e) => updateService(service.id, 'destination', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>

                  {/* Row 2 */}
                   <div>
                     <label className="text-xs text-gray-500">Veículo Rebocado</label>
                    <input type="text" placeholder="Modelo/Cor" value={service.towedVehicle} onChange={(e) => updateService(service.id, 'towedVehicle', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>
                   <div>
                     <label className="text-xs text-gray-500">Placa</label>
                    <input type="text" placeholder="ABC-1234" value={service.towedPlate} onChange={(e) => updateService(service.id, 'towedPlate', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 uppercase bg-white text-gray-900" />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Cliente</label>
                    <input type="text" placeholder="Nome" value={service.clientName} onChange={(e) => updateService(service.id, 'clientName', e.target.value)} className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900" />
                  </div>

                   {/* Payment */}
                   <div>
                    <label className="text-xs text-gray-500 font-medium">Pagamento</label>
                    <select 
                      value={service.paymentMethod} 
                      onChange={(e) => handlePaymentChange(service.id, e.target.value as PaymentMethod)} 
                      className="w-full p-2 text-sm border border-gray-300 rounded mt-1 bg-white text-gray-900 focus:ring-indigo-500 focus:border-indigo-500"
                    >
                      {Object.values(PaymentMethod).map(m => (
                        <option key={m} value={m} className="text-gray-900 bg-white">
                          {m}
                        </option>
                      ))}
                    </select>
                  </div>

                   {/* Value */}
                   <div>
                    <label className="text-xs text-gray-500 font-medium">Valor (R$)</label>
                    <input 
                      type="number" 
                      placeholder={service.paymentMethod === PaymentMethod.ON_TERM ? "Bloqueado" : "0.00"}
                      value={service.value === 0 ? '' : service.value} 
                      onChange={(e) => updateService(service.id, 'value', Number(e.target.value))} 
                      disabled={service.paymentMethod === PaymentMethod.ON_TERM}
                      className={`w-full p-2 text-sm border rounded mt-1 font-semibold transition-colors 
                        ${service.paymentMethod === PaymentMethod.ON_TERM 
                          ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed' 
                          : 'bg-white text-green-700 border-gray-300'}
                        ${service.paymentMethod !== PaymentMethod.ON_TERM && (!service.value || service.value <= 0) ? 'border-red-300 bg-red-50' : ''}
                      `}
                    />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Expenses & Observations */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 border-t pt-6">
           <div>
              <div className="flex justify-between items-center mb-2">
                 <h3 className="text-lg font-semibold text-gray-800">Despesas</h3>
                 <button type="button" onClick={addExpenseRow} className="text-sm text-indigo-600 font-medium">+ Adicionar</button>
              </div>
              {expenses.map(expense => (
                <div key={expense.id} className="flex gap-2 mb-2">
                   <input 
                    type="text" 
                    placeholder="Descrição (ex: Diesel)" 
                    value={expense.description}
                    onChange={(e) => setExpenses(expenses.map(ex => ex.id === expense.id ? { ...ex, description: e.target.value} : ex))}
                    className="flex-1 p-2 text-sm border border-gray-300 rounded bg-white text-gray-900"
                   />
                   <input 
                    type="number" 
                    placeholder="R$" 
                    value={expense.value}
                    onChange={(e) => setExpenses(expenses.map(ex => ex.id === expense.id ? { ...ex, value: Number(e.target.value)} : ex))}
                    className="w-24 p-2 text-sm border border-gray-300 rounded bg-white text-gray-900"
                   />
                </div>
              ))}
              <div className="mt-4">
                 <label className="block text-sm font-medium text-gray-700 mb-1">Observações Gerais</label>
                 <textarea 
                   rows={3} 
                   value={observations}
                   onChange={(e) => setObservations(e.target.value)}
                   className="w-full rounded-lg border-gray-300 border shadow-sm p-2 text-sm bg-white text-gray-900"
                   placeholder="Avarias, incidentes, notas..."
                 ></textarea>
              </div>
           </div>

           {/* Summary Card */}
           <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
              <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                <DollarSign className="w-5 h-5 text-green-600"/> Resumo do Dia
              </h3>

              <div className="space-y-3">
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-600">Total Faturado</span>
                    <span className="font-semibold">R$ {totalInvoiced.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between text-sm">
                    <span className="text-red-500">Despesas</span>
                    <span className="font-semibold text-red-500">- R$ {totalExpenses.toFixed(2)}</span>
                 </div>
                 <div className="border-t border-gray-300 my-2"></div>
                 <div className="flex justify-between text-sm">
                    <span className="text-gray-600">Líquido (A Prazo)</span>
                    <span className="font-medium text-blue-600">R$ {totalLiquidTerm.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between text-lg font-bold bg-green-100 p-3 rounded-lg text-green-800">
                    <span>Líquido (À Vista)</span>
                    <span>R$ {totalLiquidCash.toFixed(2)}</span>
                 </div>
              </div>
           </div>
        </div>

        {/* Submit Action */}
        <div className="mt-8 pt-4 border-t flex justify-end">
           <button 
             onClick={handleSubmit}
             disabled={isSubmitting}
             className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg transition-all transform hover:scale-105 disabled:opacity-50 disabled:scale-100"
           >
             {isSubmitting ? (
               <><Loader2 className="w-5 h-5 animate-spin" /> Enviando...</>
             ) : (
               <><Save className="w-5 h-5" /> Encerrar e Enviar</>
             )}
           </button>
        </div>

      </div>
    </div>
  );
};

export default DriverForm;

