const GAS_SCRIPT_CODE = `// =======================================================
// COLE ESTE CÓDIGO NO GOOGLE APPS SCRIPT
// =======================================================

function doGet(e) {
  return handleRequest(e);
}

function doPost(e) {
  return handleRequest(e);
}

function handleRequest(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const doc = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = doc.getSheetByName('Logs');

    // Configuração automática se a aba não existir
    if (!sheet) {
      setup(); 
      sheet = doc.getSheetByName('Logs');
    }

    // --- GET Request (Admin buscando dados) ---
    if (!e.postData) {
      const data = sheet.getDataRange().getValues();
      if (data.length < 2) return outputJSON([]); // Sem dados

      const headers = data[0];
      const rows = data.slice(1);

      const logs = rows.map(row => {
        const obj = {};
        headers.forEach((header, index) => {
          let value = row[index];
          // Converte strings JSON de volta para objetos
          if ((header === 'services' || header === 'expenses') && typeof value === 'string' && value.startsWith('[')) {
            try { value = JSON.parse(value); } catch(err) {}
          }
          // Formata datas se necessário
          if (value instanceof Date) {
            value = value.toISOString();
          }
          obj[header] = value;
        });
        return obj;
      });

      return outputJSON(logs);
    }

    // --- POST Request (Motorista enviando dados) ---
    const payload = JSON.parse(e.postData.contents);
    const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

    // Mapeia os dados recebidos para as colunas corretas
    const newRow = headers.map(header => {
      let value = payload[header];
      if (typeof value === 'object' && value !== null) {
        value = JSON.stringify(value);
      }
      return value === undefined ? '' : value;
    });

    sheet.appendRow(newRow);

    return outputJSON({ status: 'success' });

  } catch (err) {
    return outputJSON({ status: 'error', message: err.toString() });
  } finally {
    lock.releaseLock();
  }
}

function outputJSON(data) {
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function setup() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Logs');
  if (!sheet) {
    sheet = ss.insertSheet('Logs');
    // Cabeçalhos obrigatórios para o App
    sheet.appendRow([
      'id', 'userId', 'driverName', 'date', 'vehicleId', 
      'kmStart', 'kmEnd', 'services', 'expenses', 'observations', 
      'totalInvoiced', 'totalLiquidCash', 'totalLiquidTerm', 
      'totalExpenses', 'submittedAt'
    ]);
  }
}`;

