                       <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-600">{log.kmEnd - log.kmStart} km</td>
                       <td className="px-6 py-4 whitespace-nowrap text-sm text-green-600 font-semibold">R$ {log.totalInvoiced.toFixed(2)}</td>
                       <td className="px-6 py-4 text-sm text-gray-500 max-w-xs truncate">{log.observations || '-'}</td>
                    </tr>
                  )) : (
                    <tr>
                       <td colSpan={6} className="px-6 py-10 text-center text-gray-500">
                         {loadingData ? 'Carregando dados...' : 'Nenhum registro encontrado.'}
                       </td>
                    </tr>
                  )}
               </tbody>
            </table>
         </div>
      </div>

    </div>
  );
};

