  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [loadingAi, setLoadingAi] = useState(false);
  const [loadingData, setLoadingData] = useState(false);

  // Navigation State
  const [activeTab, setActiveTab] = useState<TabView>('overview');

  // Date Navigation State
  const [expandedMonths, setExpandedMonths] = useState<Set<string>>(new Set());
  const [expandedDays, setExpandedDays] = useState<Set<string>>(new Set());
  const [expandedLogs, setExpandedLogs] = useState<Set<string>>(new Set());

  // Driver Navigation State
  const [driverSearch, setDriverSearch] = useState('');
  const [selectedDriverId, setSelectedDriverId] = useState<string | null>(null);

  // Modal State
  const [showSetup, setShowSetup] = useState(false);
  const [copied, setCopied] = useState(false);

  // --- Data Loading ---
  const loadData = async () => {
    setLoadingData(true);
    if (GOOGLE_SHEET_API_URL) {
      const cloudLogs = await fetchLogsFromGoogleSheets();
      if (cloudLogs && cloudLogs.length > 0) {
          setLogs(cloudLogs);
      } else {
          const local = getAllLogs();
          if (local.length > 0) setLogs(local);
      }
    } else {
      setLogs(getAllLogs());
    }
    setLoadingData(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAiAnalysis = async () => {
    if (logs.length === 0) return;
    setLoadingAi(true);
    const result = await analyzeDailyLogs(logs);
    setAiAnalysis(result);
    setLoadingAi(false);
  };

  const copyCode = () => {
    navigator.clipboard.writeText(GAS_SCRIPT_CODE);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // --- Helpers for Grouping ---
  const getLogsByMonth = () => {
    const grouped: Record<string, Record<string, DailyLog[]>> = {};

    // Sort logs by date desc
    const sorted = [...logs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    sorted.forEach(log => {
      const dateObj = new Date(log.date);
      // Ajuste de fuso horário simples para exibição correta do mês
      const monthKey = `${dateObj.getUTCFullYear()}-${String(dateObj.getUTCMonth() + 1).padStart(2, '0')}`;
      const dayKey = log.date; // YYYY-MM-DD

      if (!grouped[monthKey]) grouped[monthKey] = {};
      if (!grouped[monthKey][dayKey]) grouped[monthKey][dayKey] = [];
      grouped[monthKey][dayKey].push(log);
    });
    return grouped;
  };

  const formatMonth = (monthKey: string) => {
    const [year, month] = monthKey.split('-');
    const date = new Date(parseInt(year), parseInt(month) - 1, 1);
    return date.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }).toUpperCase();
  };

  const toggleSet = (set: Set<string>, val: string, update: (s: Set<string>) => void) => {
