                <div className="flex flex-col">
                  <span className="flex items-center gap-1"><Clock className="w-3 h-3"/> Início: {s.startTime}</span>
                  <span className="flex items-center gap-1"><Clock className="w-3 h-3"/> Fim: {s.endTime}</span>
                </div>
              </td>
              <td className="px-3 py-2 text-gray-600">
