          {/* AI Analysis Section */}
          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
            <div className="relative z-10">
              <h3 className="text-lg font-bold mb-2 flex items-center gap-2">
                <Bot className="w-6 h-6" /> Assistente Gemini IA
              </h3>
              <p className="text-indigo-100 text-sm mb-4">
                Analise os logs para identificar padrões e anomalias.
              </p>
              {!aiAnalysis ? (
                <button onClick={handleAiAnalysis} disabled={loadingAi} className="w-full bg-white text-indigo-700 font-bold py-2 px-4 rounded-lg shadow-md hover:bg-gray-50 transition-colors disabled:opacity-70">
                  {loadingAi ? 'Analisando...' : 'Gerar Relatório'}
