  };

  const renderByDate = () => {
    const groupedLogs = getLogsByMonth();
    const months = Object.keys(groupedLogs).sort((a, b) => b.localeCompare(a));

    if (months.length === 0) {
      return <div className="p-8 text-center text-gray-500">Nenhum registro encontrado.</div>;
