import { DailyLog, User } from '../types';
import { GOOGLE_SHEET_API_URL } from '../constants';

const LOGS_KEY = 'guincholog_logs';
const USER_KEY = 'guincholog_user';

export const saveLog = (log: DailyLog): void => {
  const existingLogs = getAllLogs();
  // Filter out if updating existing ID, or just append
  const filtered = existingLogs.filter(l => l.id !== log.id);
  const updated = [...filtered, log];
  localStorage.setItem(LOGS_KEY, JSON.stringify(updated));
};

export const updateLog = async (log: DailyLog): Promise<void> => {
  // 1. Atualiza LocalStorage
  saveLog(log);

  // 2. Envia atualização para o Google Sheets (se configurado)
  if (GOOGLE_SHEET_API_URL) {
    await syncWithGoogleSheets(log, 'update');
  }
};

export const getAllLogs = (): DailyLog[] => {
  const str = localStorage.getItem(LOGS_KEY);
  return str ? JSON.parse(str) : [];
};

export const getLogsByUser = (userId: string): DailyLog[] => {
  const all = getAllLogs();
  return all.filter(log => log.userId === userId).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
};

export const getCurrentUser = (): User | null => {
  const str = localStorage.getItem(USER_KEY);
  return str ? JSON.parse(str) : null;
};

export const setCurrentUser = (user: User | null): void => {
  if (user) {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  } else {
    localStorage.removeItem(USER_KEY);
  }
};

// Envia dados para a planilha (POST)
// Adicionado parâmetro 'action' para diferenciar criação de atualização no script (se suportado)
export const syncWithGoogleSheets = async (log: DailyLog, action: 'create' | 'update' = 'create'): Promise<boolean> => {
  if (!GOOGLE_SHEET_API_URL) {
    console.warn("URL da API do Google Sheets não configurada.");
    return false;
  }

  try {
    // Enviamos action dentro do corpo para o script processar (upsert)
    const payload = { ...log, _action: action };

    const response = await fetch(GOOGLE_SHEET_API_URL, {
      method: 'POST',
      mode: 'no-cors', 
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload)
    });
    return true;
  } catch (error) {
    console.error("Erro ao enviar para Google Sheets:", error);
    return false;
  }
};

// Busca dados da planilha (GET) - Para o Admin
export const fetchLogsFromGoogleSheets = async (): Promise<DailyLog[]> => {
  if (!GOOGLE_SHEET_API_URL) {
    return [];
  }

  try {
    const response = await fetch(GOOGLE_SHEET_API_URL);
    if (!response.ok) throw new Error("Falha na rede");

    const data = await response.json();
    // Validar se é um array de logs
    if (Array.isArray(data)) {
      // Salva no localStorage do Admin para cache
      localStorage.setItem(LOGS_KEY, JSON.stringify(data));
      return data as DailyLog[];
    }
    return [];
  } catch (error) {
    console.error("Erro ao buscar dados do Google Sheets:", error);
    return getAllLogs(); // Retorna o que tem local se falhar
  }
};

