                  <span className="flex items-center gap-1"><Clock className="w-3 h-3"/> {s.startTime} - {s.endTime}</span>
                </div>
              </td>
              <td className="px-3 py-2 text-gray-600">
                <div className="flex flex-col max-w-[150px]">
