                    s.paymentMethod.includes('PRAZO') ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'}`}>
                  {s.paymentMethod}
                </span>
              </td>
              <td className="px-3 py-2 text-right font-medium text-gray-900">
