      else acc.push({ name: log.driverName, value: log.totalInvoiced });
      return acc;
    }, [] as { name: string; value: number }[]).sort((a,b) => b.value - a.value).slice(0, 10); // Top 10

    return (
      <div className="space-y-6 animate-fade-in">
